会津大学付属幼稚園はプログラミングが大好きな子供が集まる幼稚園である。園児の一人であるゆう君は、プログラミングと同じくらい数字が大好きだ。そんなゆう君は最近、表に0から9までのいずれかの数字の書かかれたプレートを

プレートは表に書かれている数字によって値段が異なる。
それらを使って作れる
購入するプレートの値段の総和が所持金額を超えなければ自由にプレートを購入できる。
同じ数字の書かれたプレートを複数枚購入しても良い。
プレートは必ず
購入後は
図１は０、１、９のプレートを購入した場合についての説明である。

この問題を解くに当たって、以下のことを参考にしても良い。
整数値を文字列に変換する方法を示す。
value を文字列として str に代入する。

#include<stdio.h>

int main(){
  int value = 123; // この値を文字列に変換する
  char str[6];     // この変数に value を文字列にしたものが入る
  sprintf(str,"%d",value);
  return 0;
}

#include<sstream>

using namespace std;

int main(){
  int value = 123; // この値を文字列に変換する
  string str;      // この変数に value を文字列にしたものが入る
  stringstream ss;
  ss << value;
  ss >> str;
  return 0;
}

class Main {
    public static void main(String args[]){
        int value = 123;           // この値を文字列に変換する
        String str = new Integer(value).toString(); // この変数に value を文字列にしたものが入る
    }
}

